from datetime import datetime

class EmailClient:
    UNREAD_STATE = "unread"
    READ_STATE = "read"

    def __init__(self, addr, capacity) -> None:
        self._addr = addr
        self._capacity = capacity
        self._inbox = []

    @property
    def addr(self):
        return self._addr

    @addr.setter
    def addr(self, value):
        self._addr = value

    @property
    def capacity(self):
        return self._capacity

    @capacity.setter
    def capacity(self, value):
        self._capacity = value

    @property
    def inbox(self):
        return self._inbox.copy()

    def send_to(self, recv, content, size):
        if not recv.is_full_with_one_more_email(size):
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            email = {
                "sender": self._addr,
                "receiver": recv.addr,
                "content": content,
                "size": size,
                "time": timestamp,
                "state": self.UNREAD_STATE
            }
            recv.append_to_inbox(email)
            return True
        else:
            self.clear_inbox(size)
            return False

    def append_to_inbox(self, email):
        self._inbox.append(email)

    def fetch(self):
        email = self.get_first_unread_email()
        if email is not None:
            self.mark_as_read(email)
        return email

    def get_first_unread_email(self):
        for email in self._inbox:
            if email['state'] == self.UNREAD_STATE:
                return email
        return None

    def mark_as_read(self, email):
        email['state'] = self.READ_STATE

    def is_full_with_one_more_email(self, size):
        return self.get_occupied_size() + size > self._capacity

    def get_occupied_size(self):
        return sum(email["size"] for email in self._inbox)

    def clear_inbox(self, size):
        if len(self._addr) == 0:
            return
        freed_space = 0
        while freed_space < size and self._inbox:
            email = self._inbox[0]
            freed_space += email['size']
            del self._inbox[0]
